mapper.select:


    inner join sys_user u on u.user_name = tputawayruledetail.create_by and u.status = '0'
    inner join sys_dept d on u.dept_id = d.dept_id and d.status = '0'


    tputawayruledetail.del_flag = '0'
     and tputawayruledetail.rule_id = #{ruleId}
     and tputawayruledetail.rule_order = #{ruleOrder}
     and tputawayruledetail.receipt_type = #{receiptType}
     and tputawayruledetail.status = #{status}
     and tputawayruledetail.rule = #{rule}


${params.dataScope}

mapper.update:
update t_put_away_rule_detail
set del_flag = '1'
where rule_id = #{ruleId}
